n = 12
X = [[Int(f"x_{i}_{j}") for j in range(n)] for i in range(n)]

s = Solver()

# Bounds
for i in range(n):
    for j in range(n):
        s.add(X[i][j] >= 0, X[i][j] < n)

# Latin square
for i in range(n):
    s.add(Distinct([X[i][j] for j in range(n)]))

for j in range(n):
    s.add(Distinct([X[i][j] for i in range(n)]))

# Idempotent diagonal
for i in range(n):
    s.add(X[i][i] == i)

# QG3: X[X[i][j]][X[j][i]] == i
# Encode using intermediate variable and pairwise constraints
for i in range(n):
    for j in range(n):
        a = X[i][j]
        b = X[j][i]
        # c represents X[a][b]
        c = Int(f"qx_{i}_{j}")
        s.add(c >= 0, c < n)
        for u in range(n):
            for v in range(n):
                s.add(Implies(And(a == u, b == v), c == X[u][v]))
        s.add(c == i)

print("Assertions:", len(s.assertions()))
print("Solving...")
result = s.check()
print("Result:", result)

if result == sat:
    m = s.model()
    grid = []
    for i in range(n):
        row = []
        for j in range(n):
            val = m.evaluate(X[i][j])
            if isinstance(val, IntNumRef):
                row.append(val.as_long())
            else:
                row.append(int(str(val)))
        grid.append(row)
    print("Solution found!")
    for row in grid:
        print(row)
    flat = [v for row in grid for v in row]
    print("Flat:", flat)
else:
