from z3 import *

n = 12

# Use a more efficient encoding with boolean variables
# x[i][j][k] = True iff cell (i,j) has value k

x = [[[Bool(f"x_{i}_{j}_{k}") for k in range(n)] for j in range(n)] for i in range(n)]

s = Solver()

# Each cell has exactly one value
for i in range(n):
    for j in range(n):
        s.add(PbEq([(x[i][j][k], 1) for k in range(n)], 1))

# Row constraints: each value appears exactly once per row
for i in range(n):
    for k in range(n):
        s.add(PbEq([(x[i][j][k], 1) for j in range(n)], 1))

# Column constraints: each value appears exactly once per column
for j in range(n):
    for k in range(n):
        s.add(PbEq([(x[i][j][k], 1) for i in range(n)], 1))

# Idempotent diagonal
for i in range(n):
    s.add(x[i][i][i])

# QG3: x[x[i][j]][x[j][i]] = i
# For all i, j, and for all a, b: if x[i][j]=a and x[j][i]=b, then x[a][b]=i
for i in range(n):
    for j in range(n):
        for a in range(n):
            for b in range(n):
                s.add(Or(Not(x[i][j][a]), Not(x[j][i][b]), x[a][b][i]))

print("Assertions:", len(s.assertions()))
print("Solving...")
result = s.check()
print("Result:", result)

if result == sat:
    m = s.model()
    grid = []
    for i in range(n):
        row = []
        for j in range(n):
            for k in range(n):
                if is_true(m.evaluate(x[i][j][k])):
                    row.append(k)
                    break
        grid.append(row)
    print("Solution found!")
    for row in grid:
        print(row)
    flat = [v for row in grid for v in row]
    print("Flat:", flat)
else:
    print("UNSAT or unknown")

